#include "../Source/PluginProcessor.h"
#include <cstdio>
#include <cstdlib>
static void stage(const char* m){std::printf("STAGE: %s\n",m);std::fflush(stdout);}
static int tests=0;static void check(bool b,const char* m){++tests;if(!b){std::fprintf(stderr,"HOST FAIL: %s\n",m);std::exit(1);}}
static double render(juce::AudioProcessor& p,int channels,int frames,bool note=true){juce::AudioBuffer<float> b(channels,frames);b.clear();juce::MidiBuffer midi;if(note)midi.addEvent(juce::MidiMessage::noteOn(1,48,.8f),0);p.processBlock(b,midi);double e=0;for(int c=0;c<channels;++c)for(int i=0;i<frames;++i){const auto x=b.getSample(c,i);check(std::isfinite(x)&&std::abs(x)<=.981f,"finite bounded output");e+=x*x;}return e;}
int main(int argc,char** argv){
    juce::ScopedJuceInitialiser_GUI gui;const auto dir=argc>2?juce::File(argv[2]):juce::File::getSpecialLocation(juce::File::tempDirectory).getChildFile("OddSynth-validation");dir.createDirectory();
    stage("construct processor");OddProcessor p;check(p.acceptsMidi(),"MIDI instrument");check(p.value("mode")==0&&p.value("reverb")==0&&p.value("delay")==0&&p.value("drive")==0,"manual and dry by default");
    for(int channels:{1,2})for(double sr:{44100.,48000.,96000.}){juce::AudioProcessor::BusesLayout l;l.outputBuses.add(channels==1?juce::AudioChannelSet::mono():juce::AudioChannelSet::stereo());check(p.setBusesLayout(l),"mono/stereo output with no input");p.prepareToPlay(sr,64);check(render(p,channels,4096)>0,"MIDI produces sound");for(int block:{1,31,256,2048})render(p,channels,block,false);p.releaseResources();}
    stage("layouts and variable blocks passed");juce::AudioProcessor::BusesLayout stereo;stereo.outputBuses.add(juce::AudioChannelSet::stereo());p.setBusesLayout(stereo);p.prepareToPlay(48000,512);
    p.setValue("rough",.38f);p.setValue("roughLock",1);p.setValue("vowelLow",.2f);p.setValue("vowelHigh",.4f);p.setValue("amount",1);p.randomise();check(p.value("rough")==.38f,"randomise preserves lock");check(p.value("vowel")>=.2f&&p.value("vowel")<=.4f,"randomise obeys range");const float varied=p.value("vowel");check(p.undoManager.undo(),"randomise undo exists");check(p.value("vowel")!=varied,"undo restores previous sound");check(p.undoManager.redo(),"randomise redo exists");
    stage("undo and random limits passed");juce::AudioBuffer<float> fixture(2,4800);for(int c=0;c<2;++c)for(int i=0;i<4800;++i)fixture.setSample(c,i,static_cast<float>(.4*std::sin(i*.04))*(c==1?-.5f:1));
    const auto file=dir.getChildFile("fixture.wav");{auto stream=file.createOutputStream();juce::WavAudioFormat wav;auto writer=std::unique_ptr<juce::AudioFormatWriter>(wav.createWriterFor(stream.get(),48000,2,24,{},0));check(writer!=nullptr,"fixture writer");stream.release();check(writer->writeFromAudioSampleBuffer(fixture,0,4800),"fixture writes");}
    juce::String error;check(p.loadSample(file,error),"external WAV loads");const auto original=p.sampleCopy();check(original&&original->left.size()==4800,"external sample length");p.setValue("sampleStart",.2f);p.setValue("sampleEnd",.7f);p.sampleEdit(1);check(p.sampleCopy()->left.size()==2400,"sample crop selection");check(p.undoManager.undo(),"sample edit undo");check(p.sampleCopy()->left==original->left,"undo restores exact audio");check(p.undoManager.redo(),"sample edit redo");
    stage("sample import/edit undo passed");p.captureSlot(0);p.setValue("roughLock",0);p.setValue("rough",.9f);p.captureSlot(1);p.morph(.5f);check(p.value("rough")>.38f&&p.value("rough")<.9f,"A B morph interpolates");p.recallSlot(0);check(std::abs(p.value("rough")-.38f)<.0001f,"A recall restores sound");
    juce::MemoryBlock state;p.getStateInformation(state);OddProcessor restored;restored.setStateInformation(state.getData(),static_cast<int>(state.getSize()));check(restored.sampleCopy()&&restored.sampleCopy()->left==p.sampleCopy()->left,"host state embeds edited sample");check(restored.hasSlot(0)&&restored.hasSlot(1),"A B preserved in state");check(restored.value("rough")==p.value("rough"),"parameters preserved in state");
    stage("embedded state and AB passed");for(const auto* id:{"material","throat","swarm","pulse"})p.setValue(id,0);p.setValue("sampleMix",1);check(render(p,2,8192)>0,"imported sample actually plays via MIDI");check(p.exportSample(dir.getChildFile("edited.wav")),"edited sample exports");check(p.exportCapture(dir.getChildFile("capture.wav")),"recent sound exports");auto parkedAudio=p.captureSnapshot();check(parkedAudio!=nullptr,"retrospective audio snapshot exists");const auto parkedSamples=parkedAudio->left;render(p,2,4096,false);check(parkedAudio->left==parkedSamples,"captured moment is stable while audio and file chooser continue");
    {std::unique_ptr<juce::AudioProcessorEditor> editor(restored.createEditor());check(editor!=nullptr,"native UI constructs");for(int tab=0;tab<2;++tab){for(int i=0;i<editor->getNumChildComponents();++i)if(auto* t=dynamic_cast<juce::TabbedComponent*>(editor->getChildComponent(i)))t->setCurrentTabIndex(tab);auto image=editor->createComponentSnapshot(editor->getLocalBounds());auto stream=dir.getChildFile(tab==0?"OddSynth_Instrumento.png":"OddSynth_Samples.png").createOutputStream();juce::PNGImageFormat png;check(stream&&png.writeImageToStream(image,*stream),"UI screenshot saved");}}
    stage("native UI created and destroyed");{OddProcessor frozen;frozen.prepareToPlay(48000,256);frozen.setValue("mode",2);frozen.setValue("amount",1);frozen.setValue("rate",1);render(frozen,2,16384);frozen.setValue("freeze",1);render(frozen,2,512,false);std::array<float,6> expected;for(size_t i=0;i<expected.size();++i)expected[i]=frozen.live[i].load();juce::MemoryBlock parked;frozen.getStateInformation(parked);OddProcessor recovered;recovered.setStateInformation(parked.getData(),static_cast<int>(parked.getSize()));recovered.prepareToPlay(48000,256);render(recovered,2,512,false);for(size_t i=0;i<expected.size();++i)check(std::abs(recovered.live[i].load()-expected[i])<1e-6f,"saved freeze restores audible parameter values after prepare");}
    stage("saved frozen motion passed");if(argc>1){juce::AudioPluginFormatManager formats;formats.addFormat(new juce::VST3PluginFormat);juce::OwnedArray<juce::PluginDescription> desc;formats.getFormat(0)->findAllTypesForFile(desc,juce::String(argv[1]));check(desc.size()==1,"actual compiled VST3 discoverable");juce::String failure;auto instance=formats.createPluginInstance(*desc[0],48000,512,failure);if(!instance)std::fprintf(stderr,"VST3: %s\n",failure.toRawUTF8());check(instance!=nullptr,"actual compiled VST3 loads");stage("native VST3 scanned and loaded");instance->prepareToPlay(48000,512);double nativeEnergy=0;for(int block=0;block<16;++block)nativeEnergy+=render(*instance,2,512,block==0);check(nativeEnergy>0,"actual VST3 produces audio from MIDI within negotiated block size");stage("native VST3 audio passed");
        juce::XmlElement container("VST3PluginState");container.createNewChildElement("IComponent")->addTextElement(state.toBase64Encoding());juce::MemoryBlock hostState;juce::AudioProcessor::copyXmlToBinary(container,hostState);instance->setStateInformation(hostState.getData(),static_cast<int>(hostState.getSize()));juce::MemoryBlock native;instance->getStateInformation(native);auto xml=juce::AudioProcessor::getXmlFromBinary(native.getData(),static_cast<int>(native.getSize()));check(xml!=nullptr,"native state wrapper exists");auto* component=xml->getChildByName("IComponent");check(component!=nullptr,"native component exists");juce::MemoryBlock inner;check(inner.fromBase64Encoding(component->getAllSubText()),"native state decodes");OddProcessor round;round.setStateInformation(inner.getData(),static_cast<int>(inner.getSize()));check(round.sampleCopy()&&round.sampleCopy()->left==p.sampleCopy()->left,"actual VST3 preserves embedded audio");instance->releaseResources();
    }
    std::printf("OddSynth native host: %d checks passed\n",tests);
}
